class FrozenSequential(nn.Sequential):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.frozen_modules_idx = []
        self.shared_modules_idx = []

    def requires_grad(self):
        return any(map(lambda t: t.requires_grad, self.parameters()))

    def forward(self, *args, **kwargs):
        for i in self.frozen_modules_idx:
            self[i].eval()
        return super().forward(*args, **kwargs)

    def feats_forward(self, input):
        for i in self.frozen_modules_idx:
            self[i].eval()
        feats = self[:-1](input)
        return feats, self[-1](feats)

    def arch_repr(self):
        detail = {}
        for block in self:
            detail[len(detail)] = count_params(block)['trainable']
        return detail

def _conv_block(in_dim, out_dim, k, stride, pad, dropout_p, pool, pool_k, is_last):
    assert len(in_dim) == 3
    layers = [nn.Conv2d(in_dim[0], out_dim[0], k, stride, pad)]
    if not is_last:
        layers.append(nn.ReLU())
        if dropout_p is not None: layers.append(nn.Dropout(dropout_p))
    if pool is not None:
        assert pool == 'maxpool', 'Only Maxpool supported for now'
        layers.append(nn.MaxPool2d(pool_k))
    return layers

def _lin_block(in_dim, out_dim, dropout_p, is_last):
    layers = []
    if not isinstance(in_dim, int):
        in_dim = in_dim[0] * in_dim[1] * in_dim[2]
        layers.append(Flatten())
    layers.append(nn.Linear(in_dim, out_dim))
    if not is_last:
        layers += [nn.ReLU()]
        if dropout_p is not None: layers.append(nn.Dropout(dropout_p))
    return layers

def get_block(in_dim, out_dim, dropout_p, k, stride, pad, pool, pool_k,
              norm_layer, is_first, is_last, residual, block_depth):
    if residual:
        if isinstance(in_dim, (list, tuple)): assert len(in_dim) == 3
        layers = _make_layer(BasicBlock, in_dim, out_dim, block_depth, stride,
                       pool, pool_k, norm_layer=norm_layer, is_first=is_first,
                             is_last=is_last)
    elif isinstance(out_dim, int) or len(out_dim) == 1:
        layers = _lin_block(in_dim, out_dim, dropout_p, is_last)
    elif len(out_dim) == 3:
        layers = _conv_block(in_dim, out_dim, k, stride, pad, dropout_p,
                             pool, pool_k, is_last)
    else:
        raise ValueError('Don\'t know which kind of layer to use for input '
                         'size {} and output size {}.'.format(in_dim, out_dim))
    return nn.Sequential(*layers)

# --- From src/models/resnet.py (helper blocks) ---
class Contiguousize(nn.Module):
    def forward(self, x): return x.contiguous()

class BasicBlock(nn.Module):
    expansion = 1
    def __init__(self, in_dim, out_dim, stride=1, downsample=None,
                 norm_layer=None, end_act=True):
        super().__init__()
        assert isinstance(in_dim, (tuple, list)); in_planes = in_dim[0]
        assert isinstance(out_dim, (tuple, list)); out_planes = out_dim[0]
        self.conv1 = conv3x3(in_planes, out_planes, stride)
        self.norm1 = get_norm_layer(norm_layer, out_dim)
        self.relu = nn.ReLU()
        self.conv2 = conv3x3(out_planes, out_planes)
        self.norm2 = get_norm_layer(norm_layer, out_dim)
        self.downsample = downsample
        self.stride = stride
        self.end_act = end_act

    def forward(self, x):
        identity = x
        out = self.conv1(x)
        out = self.norm1(out)
        out = self.relu(out)
        out = self.conv2(out)
        out = self.norm2(out)
        if self.downsample is not None: identity = self.downsample(x)
        out += identity
        if self.end_act: out = self.relu(out)
        return out

def get_norm_layer(norm_layer, in_size):
    assert len(in_size) == 3, 'Normalization should be applied on 3D '
                              'feature maps, got shape {}'.format(in_size)
    if norm_layer == 'batch': return nn.BatchNorm2d(num_features=in_size[0], affine=True)
    elif norm_layer == 'layer': return nn.LayerNorm(normalized_shape=in_size[1:], elementwise_affine=True)
    elif norm_layer == 'instance': return nn.InstanceNorm2d(num_features=in_size[0], affine=True)
    raise ValueError('Unknown normalzation: {}'.format(norm_layer))

def _make_layer(block, in_dim, out_dim, blocks, stride=1, pool=None,
                pool_size=None, norm_layer=None, is_first=False,
                is_last=False, end_act=True, n_blocks=None):
    if n_blocks is None: n_blocks = 1 if is_first or is_last else blocks
    if stride is None: stride = []
    elif isinstance(stride, int): stride = [stride] + [1]*(n_blocks-1)
    if isinstance(in_dim[0], int): in_dim = [in_dim] + [out_dim] * (n_blocks-1)
    if isinstance(out_dim, int): out_dim = [out_dim]
    elif isinstance(out_dim[0], int): out_dim = [out_dim] * n_blocks
    if pool_size is None or isinstance(pool_size, int): pool_size = [None] * (n_blocks-1) + [pool_size]
    assert len(stride) == n_blocks or is_last and len(stride) == n_blocks - 1

    layers = []
    if is_first:
        in_size, in_dim_rem = in_dim[0], in_dim[1:]
        in_planes = in_size[0]
        out_size, out_dim_rem = out_dim[0], out_dim[1:]
        out_planes = out_size[0]
        s, stride_rem = stride[0], stride[1:]
        p, pool_size_rem = pool_size[0], pool_size[1:]
        layers.extend([conv3x3(in_planes, out_planes),
                get_norm_layer(norm_layer, out_size)])
        if end_act: layers.append(nn.ReLU())
        in_dim, out_dim, stride, pool_size = in_dim_rem, out_dim_rem, stride_rem, pool_size_rem

    assert len(stride) <= len(in_dim) and len(stride) <= len(out_dim)
    for l in range(len(stride)):
        in_s, in_dim_rem = in_dim[0], in_dim[1:]
        out_s, out_dim_rem = out_dim[0], out_dim[1:]
        s, stride_rem = stride[0], stride[1:]
        downsample = None
        if s != 1 or in_s[0] != out_s[0]:
            downsample = nn.Sequential(
                Contiguousize(),
                conv1x1(in_s[0], out_s[0], s),
                get_norm_layer(norm_layer, out_s),
            )
        layers.append(block(in_s, out_s, s, downsample, norm_layer, end_act or l < blocks - 1))
        p, pool_size_rem = pool_size[0], pool_size[1:]
        if p is not None:
            layers.append(nn.ReLU())
            layers.append(get_pool_l(pool, p))
        in_dim, out_dim, stride, pool_size = in_dim_rem, out_dim_rem, stride_rem, pool_size_rem

    assert not stride
    assert not any(pool_size)

    if is_last:
        in_size, in_dim_rem = in_dim[0], in_dim[1:]
        in_planes = in_size[0]
        out_size, out_dim_rem = out_dim[0], out_dim[1:]
        if not isinstance(out_size, int): assert len(out_size) == 1; out_size = out_size[0]
        assert len(in_size) == 3
        layers.extend([Flatten(), nn.Linear(in_planes, out_size)])
    return layers

def get_pool_l(p_type, p_size):
    if p_type == 'avgpool': pool_l = nn.AdaptiveAvgPool2d
    elif p_type == 'maxpool': pool_l = nn.AdaptiveMaxPool2d
    else: raise NotImplementedError()
    return pool_l(1)

# --- From src/models/samplers/arch_sampler.py ---
class ArchSampler(nn.Module):
    def __init__(self, distrib_dim, all_same, deter_eval, var_names=None,
                 *args, **kwargs):
        super().__init__()
        self.distrib_dim = distrib_dim
        self.all_same = all_same
        self.deter_eval = deter_eval
        self.frozen = False
        self.log_probas = None
        self.distrib_entropies = None
        self._seq_probas = None

        if var_names is not None: assert len(var_names) == self.distrib_dim
        self.var_names = var_names

    def freeze(self): self.frozen = True

    def start_new_sequence(self): self.log_probas = []; self.distrib_entropies = []; self._seq_probas = []

    def nodes_to_prune(self, treshold):
        nodes = []
        for node, weight in zip(self.var_names, self().squeeze().unbind()):
            if weight < treshold: nodes.append(node)
        return nodes

    def sample_archs(self, batch_size, probas):
        self._check_probas(probas, self.all_same)
        if probas.size(0) != batch_size:
            if probas.size(0) != 1: raise ValueError('Sampling probabilities dimensions {} doesn\'t match with batch size {}.'.format(probas.size(), batch_size))
            if not self.all_same: probas = probas.expand(batch_size, -1)

        distrib = Bernoulli(probas)
        if not self.training and self.deter_eval: samplings = (probas > 0.5).float()
        else: samplings = distrib.sample()

        if self.all_same: samplings = samplings.expand(batch_size, -1)

        self._seq_probas.append(probas)
        self.distrib_entropies.append(distrib.entropy())
        self.log_probas.append(distrib.log_prob(samplings))
        return samplings

    def _check_probas(self, probas, all_same):
        if probas.dim() != 2 or all_same and probas.size(0) != 1:
            raise ValueError('probas params has wrong dimension: {} (all_same={})'.format(probas.size(), all_same))

        if probas.size(-1) != self.distrib_dim:
            raise ValueError('Should have exactly as many probas as the '
                             'number of stochastic nodes({}), got {} instead.'.format(self.distrib_dim, probas.size(-1)))

    @property
    def last_sequence_probas(self): return torch.stack(self._seq_probas)

