        for node in graph.nodes:
            mod = graph.nodes[node]['module']
            if not (self.single_stage or mod in frozen_modules): self.block_inits[node] = deepcopy(mod.state_dict())
            if node in stochastic_nodes:
                if node not in graph: nodes_to_raise.append(node)
                self.register_stochastic_node(node)

        if nodes_to_raise: raise ValueError('Nodes to register not in graph {}'.format(nodes_to_raise))
        self.set_graph(self.graph, [in_node], [out_node])

