        else: self.n_modules = len(self.hidden_size) + 1

        self.arch_sampler_type = arch_sampler_type
        self.arch_samplers = []
        self.search_res = []
        self.knn_res = []
        self.method = method

        self.arch_loss_coef = arch_loss_coef
        self.entropy_coef = entropy_coef
