    def get_candidate_models(self, task_id, descriptor, dataset, topk, n_neighbors, max_samples=1000):
        if topk == -1: return list(range(task_id))
        device = 'cuda' if torch.cuda.is_available() else 'cpu'
        train, val = dataset
        knn_perfs = []; model_perfs = []; rand_dists = []
        for t_id_past in range(task_id):
            model = self.get_model(t_id_past); pruned_model = model.get_frozen_model(); pruned_model.to(device)
            features, model_preds, labels = [], [], []
            with torch.no_grad():
                n_samples_acc = 0
                for x, y in train: 
                    x = x.to(device); y = y.to(device)
                    feats, preds = pruned_model.feats_forward(x)
                    features.append(flatten(feats)); model_preds.append(preds); labels.append(y)
                    n_samples_acc += x.size(0); if n_samples_acc >= max_samples: break
                features = torch.cat(features, 0); model_preds = torch.cat(model_preds, 0); labels = torch.cat(labels, 0).flatten()
            n_neighbors_knn = min(n_neighbors, features.size(0))
            knn = KNeighborsClassifier(n_neighbors=n_neighbors_knn); knn.fit(features.cpu(), labels.cpu())
            preds_knn, gt_knn = [], []
            with torch.no_grad():
                n_samples_acc = 0
                for x, y in val:
                    x = x.to(device); y = y.to(device)
                    feats, _ = pruned_model.feats_forward(x); feats = flatten(feats).cpu()
                    preds_knn.append(torch.tensor(knn.predict(feats))); gt_knn.append(y.flatten())
                    n_samples_acc += x.size(0); if n_samples_acc >= max_samples: break
                preds_knn = torch.cat(preds_knn, 0).to(device); gt_knn = torch.cat(gt_knn, 0)
                knn_perfs.append((preds_knn == gt_knn).float().mean().item())
                acc = (model_preds.argmax(1) == labels).float().mean().item(); model_perfs.append(acc)
                rand_dists.append(abs(1/model_preds.size(1) - acc))
        self.arch_scores[task_id]['task id'] = list(range(task_id)); self.arch_scores[task_id]['knn'] = knn_perfs
        self.arch_scores[task_id]['accs'] = model_perfs; self.arch_scores[task_id]['rand dist'] = rand_dists

        if not hasattr(self, 'method'): self.method = 'knn'
        if self.method == 'knn': arg_res = np.argsort(knn_perfs); self.knn_res.append({k: knn_perfs[k] for k in arg_res})
        elif self.method == 'best-rand': arg_res = np.argsort(rand_dists); self.knn_res.append({k: rand_dists[k] for k in arg_res})
        elif self.method == 'rand': arg_res = np.random.choice(task_id, task_id, replace=False); self.knn_res.append({k: knn_perfs[k] for k in arg_res})
        else: raise ValueError(f'unknown method {self.method}')
        res = arg_res[-topk:].tolist()
        return res

    def get_nodes_from_models(self, model_ids): nodes = set(); [nodes.update(self.fixed_graphs[mod].nodes) for mod in model_ids]; return nodes

    def get_backward_lateral_connections(self, col_id, targ_depth, candidate_nodes, is_last):
        assert len(self.columns) == col_id + 1; lateral_connections = {}
        if 'bw' not in self.connections or is_last: return lateral_connections
        for targ_col_id, targ_col in enumerate(self.columns[:col_id]):
            targ_layer = targ_col.get(targ_depth); targ_node = (targ_col_id, targ_depth)
            if targ_layer and targ_node in targ_layer and targ_node in candidate_nodes:
                lateral_connections[targ_col_id] = self.column_repr_sizes[targ_col_id][targ_depth]
        return lateral_connections

    def get_forward_lateral_connections(self, col_id, depth, candidate_nodes):
        assert len(self.columns) == col_id + 1; lateral_connections = {}
        if 'fw' not in self.connections or depth == 1: return lateral_connections
        for src_col_id, src_col in enumerate(self.columns[:col_id]):
            src_layer = src_col.get(depth - 1); src_node = (src_col_id, depth - 1)
            if src_layer and src_node in src_layer and src_node in candidate_nodes:
                repr_size = self.column_repr_sizes[src_col_id]
                lateral_connections[src_col_id] = repr_size[depth - 1] if len(repr_size) >= depth else -1
        return lateral_connections

    def add_column(self, sizes, candidate_nodes):
        new_col_id = len(self.columns); self.columns.append({}); 
        in_nodes = self.connect_new_input(new_col_id, candidate_nodes); self.columns[new_col_id][self.IN_NODE] = in_nodes
        in_size = sizes[0]
        for depth in range(1, self.n_modules+1):
            out_size = sizes[depth] if depth < len(sizes) else None
            f_connections = self.get_forward_lateral_connections(new_col_id, depth, candidate_nodes)
            is_last_layer = depth == self.n_modules
            backward_connections = self.get_backward_lateral_connections(new_col_id, depth, candidate_nodes, is_last_layer)
            out_activations = not is_last_layer
            new_modules = self.add_layer(f_connections, backward_connections, depth, new_col_id, out_activations, in_size, out_size)
            in_size = out_size
            self.columns[-1][depth] = new_modules
        out_nodes = self.connect_new_output(new_col_id, candidate_nodes); self.columns[new_col_id][self.OUT_NODE] = out_nodes

    def connect_new_output(self, col_id, candidate_nodes):
        new_out = (col_id, self.OUT_NODE); mod = Add_Block(False); self.graph.add_node(new_out, module=mod)
        out_connections = {new_out: mod}
        for prev_col_id in range(col_id + 1):
            last_layer_depth = self.n_modules; last_node = (prev_col_id, last_layer_depth)
            if not self.columns[prev_col_id].get(last_layer_depth) or last_node not in self.columns[prev_col_id][last_layer_depth] or last_node not in candidate_nodes | {(col_id, last_layer_depth)}: continue
            if self.learn_in_and_out:
                conn_name = (col_id, self.OUT_NODE, prev_col_id); mod = DummyBlock(); out_connections[conn_name] = mod
                self.graph.add_node(conn_name, module=mod); self.graph.add_edge(last_node, conn_name); self.graph.add_edge(conn_name, new_out)
            else: self.graph.add_edge(last_node, new_out)
        return out_connections

    def connect_new_input(self, col_id, candidate_nodes):
        new_input = (col_id, self.IN_NODE); mod = DummyBlock(); self.graph.add_node(new_input, module=mod)
        mod_0 = DummyBlock(); self.graph.add_node((col_id, 0), module=mod_0); self.columns[col_id][0] = {(col_id, 0): mod_0}
        input_connections = {new_input: mod}
        for prev_col_id in range(col_id + 1):
            in_layer = self.columns[prev_col_id].get(0); target_node = (prev_col_id, 0)
            if not in_layer or target_node not in in_layer or target_node not in candidate_nodes | {(col_id, 0)}: continue
            if self.learn_in_and_out:
                conn_name = (col_id, self.IN_NODE, prev_col_id); mod_conn = DummyBlock(); input_connections[conn_name] = mod_conn
                self.graph.add_node(conn_name, module=mod_conn); self.graph.add_edge(new_input, conn_name); self.graph.add_edge(conn_name, target_node)
            else: self.graph.add_edge(new_input, target_node)
        return input_connections

    def add_layer(self, f_connections, b_connections, depth, col_id, out_act, in_size, out_size):
        h_name = (col_id, depth); h = get_aggreg_block(None, out_act); self.graph.add_node(h_name, module=h)
        w_name = (col_id, depth, 'w'); w = self.get_module(in_size, out_size, depth - 1); self.graph.add_node(w_name, module=w)
        src_node = (col_id, self.IN_NODE) if depth == 0 else (col_id, depth - 1)
        self.graph.add_edge(src_node, w_name); self.graph.add_edge(w_name, h_name); added_modules = {w_name: w, h_name: h}

        u_name = (col_id, depth, 'u')
        for source_column, size in f_connections.items():
            if self.use_adapters: raise NotImplementedError('Need to figure out what to do with pooling')
            else: mod = self.get_module(size, out_size, depth - 1); lateral_out_node = h_name
            proj_name = (col_id, depth, source_column, 'f'); source = (source_column, depth - 1)
            self.graph.add_node(proj_name, module=mod); self.graph.add_edge(source, proj_name); self.graph.add_edge(proj_name, lateral_out_node)
            added_modules[proj_name] = mod

        r_name = (col_id, depth, 'r')
        for target_column, size in b_connections.items():
            if self.use_adapters: raise NotImplementedError('Need to figure out what to do with pooling')
            else: mod = self.get_module(in_size, size, depth - 1); lateral_in_node = src_node
            proj_name = (col_id, depth, target_column, 'b'); target = (target_column, depth)
            self.graph.add_node(proj_name, module=mod); self.graph.add_edge(lateral_in_node, proj_name); self.graph.add_edge(proj_name, target)
            added_modules[proj_name] = mod

