            res_stride = self._res_stride[resnet_block_ids_bis]
            if is_last2: res_stride = res_stride[:-1]
            res_pool = self._res_pool_k[resnet_block_ids_bis]
            layers = _make_layer(BasicBlock, in_size_res, out_size_res, self.block_depth, res_stride, self.pool, res_pool, norm_layer=self.norm_layer, is_first=is_first, is_last=is_last2, end_act=True, n_blocks=resnet_block_ids_bis.sum())
        elif isinstance(out_size, int) or (isinstance(out_size, (list, tuple)) and len(out_size) == 1):
            drop_p = self.get_dropout_p(depth); is_last = depth == self.n_modules - 1
            layers = _lin_block(in_size, out_size, dropout_p=drop_p, is_last=is_last)
        elif isinstance(out_size, (list, tuple)) and len(out_size) == 3:
            assert depth < self.n_convs
            stride = 1 if is_adapter else self.get_stride(depth); k = 1 if is_adapter else self.get_k(depth)
            pad = self.get_pad(depth); pool_k = self.get_pool_k(depth); drop_p = self.get_dropout_p(depth)
            is_last = depth == self.n_modules - 1
            layers = _conv_block(in_size, out_size, k, stride, pad, dropout_p=drop_p, pool=self.pool, pool_k=pool_k, is_last=is_last)
        else: raise ValueError('Don\'t know which kind of layer to use for input size {} and output size {}.'.format(in_size, out_size))
        return nn.Sequential(*layers)

    def get_model(self, task_id, **task_infos):
