                arch_sampler = self.arch_sampler_type if new_task else self.arch_samplers[task_id]
                model = SSNWrapper(ssn_model=ssn, initial_p=self.initial_p, deter_eval=self.deter_eval, arch_loss_coef=self.arch_loss_coef, entropy_coef=self.entropy_coef, split_training=self.split_training, t_id=task_id, all_same=False, arch_sampler=arch_sampler)
                if new_task: self.arch_samplers.append(model.arch_sampler)
