def clean_graph(g, in_node, out_node):
    used_nodes = set()
    for path in networkx.all_simple_paths(g, in_node, out_node): used_nodes.update(path)
    nodes_to_remove = set(g.nodes) - used_nodes
    return nodes_to_remove

