class MyTensorDataset(Dataset):
    def __init__(self, *tensors, transforms=None):
        if transforms: assert tensors[0][0].dim() == 3
        self.transforms = transforms
        assert all(tensors[0].size(0) == tensor.size(0) for tensor in tensors)
        self.tensors = tensors

    def __getitem__(self, index):
        res = [tensor[index] for tensor in self.tensors]
        if self.transforms: res[0] = self.transforms(res[0])
        return tuple(res)

    def __len__(self): return self.tensors[0].size(0)

def pad_seq(seq, length, val):
    new_elems = [val] * (length - len(seq))
    return seq + new_elems

def set_optim_params(optim_func, optim_params, model, split_optims):
    if isinstance(optim_params, dict): optim_params = [optim_params]
    if hasattr(model, 'param_groups'): param_groups = model.param_groups()
    else: param_groups = [{'params': model.parameters()}]
    assert len(param_groups) == len(optim_params)

    for param_group, group_opt in zip(param_groups, optim_params): param_group.update(group_opt)
    if split_optims: return [optim_func([pg]) for pg in param_groups]
    else: return optim_func(param_groups)

def strat_split_from_y(ds, split_ratio=0.5, y_idx=1):
    assert isinstance(ds, MyTensorDataset), ds
    n_classes = ds.tensors[y_idx].unique().numel()
    n_samples_per_class, mod = divmod(len(ds), n_classes); assert mod == 0
    n_samples_per_class *= split_ratio

    class_counts = defaultdict(int); train_data = []; train_label = []; test_data = []; test_label = []

    for data, label in zip(*ds.tensors):
        c = label.item()
        if class_counts[c] < n_samples_per_class: train_data.append(data); train_label.append(label); class_counts[c] += 1
        else: test_data.append(data); test_label.append(label)

    train_data = torch.stack(train_data); train_label = torch.stack(train_label)
    train_name = torch.zeros(train_data.size(0)).int()
    test_data = torch.stack(test_data); test_label = torch.stack(test_label)
    test_name = torch.ones(test_data.size(0)).int()

    trans = ds.transforms
    return (MyTensorDataset(train_data, train_label, train_name, transforms=trans),
            MyTensorDataset(test_data, test_label, test_name, transforms=trans))


class RoundRobinDataloader(DataLoader):
    def __init__(self, dataloaders): super().__init__(None); assert all(isinstance(dl, DataLoader) for dl in dataloaders); self.dataloaders = dataloaders
    def __iter__(self): return roundrobin(*self.dataloaders)
    def __len__(self): return sum(len(dl) for dl in self.dataloaders)


def _load_datasets(task, splits=None, transforms=None, normalize=False):
    if splits is None: splits = task['split_names']
    if isinstance(splits, str): splits = [splits]
    if transforms is None: transforms = [[] for _ in range(len(splits))]
    if normalize:
        assert 'statistics' in task
        t = transforms.Normalize(**task['statistics'])
        transforms = [split_trans + [t] for split_trans in transforms]

    datasets = []
    for split, trans in zip(splits, transforms):
        split_idx = task['split_names'].index(split)
        split_path = task['data_path'][split_idx]
        x, y = torch.load(split_path)
        trans = transforms.Compose(trans) if trans else None
        datasets.append(MyTensorDataset(x, y, transforms=trans))
    return datasets


