    if single_pass: max_epoch = 1
    elif n_ep_max is None: assert n_it_max is not None; max_epoch = int(n_it_max / epoch_steps) + 1
    else: assert n_it_max is None; max_epoch = n_ep_max

    all_metrics = defaultdict(dict)
    trainer = create_supervised_trainer(model, optimizer, loss_fn, device=device, prepare_batch=prepare_batch)

    if hasattr(model, 'new_epoch_hook'): trainer.add_event_handler(Events.EPOCH_STARTED, model.new_epoch_hook)
    if hasattr(model, 'new_iter_hook'): trainer.add_event_handler(Events.ITERATION_STARTED, model.new_iter_hook)
    trainer.logger.setLevel(logging.WARNING)

    train_loss = RunningAverage(output_transform=lambda out: out[3].item(), epoch_bound=True); train_loss.attach(trainer, 'Trainer loss')

    if hasattr(model, 'arch_sampler') and model.arch_sampler.distrib_dim > 0:
