def proj_grad(a, b, binary, always_proj):
    # project b to the direction of a

    dotp = torch.dot(a,b)
    if dotp >= 0:
        if not always_proj:
            return b
        else:
            return b - (torch.dot(-a,b) / torch.dot(a,a)) * a
    else:
        if binary: return torch.zeros_like(a)
        else: return b - (torch.dot(a,b) / torch.dot(a,a)) * a
